let texto = $input.first().json.csv || '';
if (texto.charCodeAt(0) === 0xfeff) texto = texto.slice(1);

function lerCsv(s) {
  const linhas = [];
  let campo = '';
  let linha = [];
  let dentro = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (dentro) {
      if (c === '"') {
        if (s[i + 1] === '"') { campo += '"'; i++; }
        else dentro = false;
      } else campo += c;
    } else {
      if (c === '"') dentro = true;
      else if (c === ',') { linha.push(campo); campo = ''; }
      else if (c === '\r') { /* ignora */ }
      else if (c === '\n') { linha.push(campo); linhas.push(linha); linha = []; campo = ''; }
      else campo += c;
    }
  }
  if (campo !== '' || linha.length) { linha.push(campo); linhas.push(linha); }
  return linhas;
}

const values = lerCsv(texto).filter(l => l.length > 1);
if (values.length < 100) throw new Error('CSV veio incompleto: ' + values.length + ' linhas');

const cab = values[0];
const iTipo = cab.indexOf('tipo');
const feed = values.slice(1).filter(l => l[iTipo] === 'feed').length;

return [{ json: { values, total: values.length - 1, feed, colunas: cab.length } }];

const c = $('Converter CSV').first().json;
const r = $input.first().json || {};
const u = r.updates || {};
return [{ json: {
  linhas_no_csv: c.total,
  posts_de_feed: c.feed,
  colunas: c.colunas,
  linhas_gravadas: u.updatedRows || null,
  confere: (u.updatedRows || 0) === c.total + 1 ? 'ok' : 'CONFERIR'
} }];
